
// ============================================================
// MD. EMON HASSAN — WEBSITE ENGINE
// Do not edit this file unless you need to change functionality.
// All personal information is stored in content.js.
// ============================================================

(() => {
  "use strict";

  const $ = id => document.getElementById(id);

  // ----------------------------------------------------------
  // BASIC HELPERS
  // ----------------------------------------------------------

  const escapeHTML = value => String(value ?? "").replace(/[&<>"']/g, char => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;"
  }[char]));

  const formatFormula = value => escapeHTML(value)
    .replace(/([A-Za-z])(\d+)(?![\d.])/g, "$1<sub>$2</sub>");

  const safeURL = value => {
    const url = String(value || "").trim();

    if (/^(https?:\/\/|mailto:)/i.test(url)) {
      return url;
    }

    return "";
  };

  const initials = name => String(name || "EH")
    .split(/\s+/)
    .filter(Boolean)
    .map(part => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();

  const setText = (id, value) => {
    const element = $(id);
    if (element) element.textContent = value ?? "";
  };

  // ----------------------------------------------------------
  // VALIDATE CONTENT
  // ----------------------------------------------------------

  const requiredData = [
    "PROFILE",
    "LINKS",
    "ABOUT",
    "EDUCATION",
    "EXPERIENCE",
    "INTERESTS",
    "PUBLICATIONS",
    "TALKS",
    "SKILLS"
  ];

  if (typeof PROFILE === "undefined" ||
      typeof PUBLICATIONS === "undefined" ||
      typeof EDUCATION === "undefined") {
    document.body.innerHTML = `
      <main style="max-width:700px;margin:80px auto;padding:25px;font-family:Arial,sans-serif">
        <h1>Website content could not be loaded.</h1>
        <p>Please check that content.js is uploaded to the repository root
        and that its filename is exactly <b>content.js</b>.</p>
      </main>`;
    return;
  }

  // ----------------------------------------------------------
  // PROFILE INFORMATION
  // ----------------------------------------------------------

  document.title = PROFILE.pageTitle || PROFILE.name;

  setText("navName", PROFILE.navName || PROFILE.name);
  setText("navSub", PROFILE.navSub || "Academic Research");

  setText("profileName", PROFILE.name);
  setText("profileRole", PROFILE.role);
  setText("profileLocation", PROFILE.location);

  setText("statPublications", PROFILE.statPublications);
  setText("statConferences", PROFILE.statConferences);
  setText("statThird", PROFILE.statThirdValue);
  setText("statThirdLabel", PROFILE.statThirdLabel);

  setText("footerName", PROFILE.name);
  setText("footerYear", new Date().getFullYear());
  setText("footerText", FOOTER_TEXT || "");

  const profilePhoto = $("profilePhoto");

  if (profilePhoto) {
    profilePhoto.alt = PROFILE.name || "Researcher portrait";

    const photoPath = PROFILE.photo || "";

    if (photoPath) {
      profilePhoto.src = photoPath;
    } else {
      profilePhoto.hidden = true;
    }

    profilePhoto.addEventListener("error", () => {
      const fallback = document.createElement("div");
      fallback.className = "photo-fallback";
      fallback.textContent = initials(PROFILE.name);
      fallback.setAttribute("role", "img");
      fallback.setAttribute("aria-label", PROFILE.name);
      profilePhoto.replaceWith(fallback);
    }, { once: true });
  }

  // Badges
  const badgesHost = $("profileBadges");

  if (badgesHost) {
    badgesHost.innerHTML = (PROFILE.badges || [])
      .map(item => `<span class="profile-badge">${escapeHTML(item)}</span>`)
      .join("");
  }

  // Social and academic links
  const linksHost = $("profileLinks");

  if (linksHost) {
    linksHost.innerHTML = (LINKS || [])
      .filter(item => Array.isArray(item) && safeURL(item[1]))
      .map(([label, url]) => {
        const href = escapeHTML(safeURL(url));
        const external = !href.startsWith("mailto:");

        return `
          <a href="${href}"
             ${external ? 'target="_blank" rel="noopener noreferrer"' : ""}
             class="profile-link">
            ${escapeHTML(label)}
          </a>`;
      })
      .join("");
  }

  // CV button appears only when a CV path is provided.
  const cvButton = $("cvButton");
  const cvPath = safeURL(PROFILE.cv);

  if (cvButton) {
    if (cvPath) {
      cvButton.href = cvPath;
      cvButton.hidden = false;
      cvButton.setAttribute("download", "");
    } else {
      cvButton.hidden = true;
    }
  }

  // ----------------------------------------------------------
  // ABOUT ME
  // ----------------------------------------------------------

  const aboutHost = $("aboutText");

  if (aboutHost) {
    aboutHost.innerHTML = (ABOUT || [])
      .map(paragraph => `<p>${escapeHTML(paragraph)}</p>`)
      .join("");
  }

  const quickHost = $("quickInterests");

  if (quickHost) {
    quickHost.innerHTML = (QUICK_INTERESTS || [])
      .map(item => `<span>${escapeHTML(item)}</span>`)
      .join("");
  }

  // ----------------------------------------------------------
  // EDUCATION
  // ----------------------------------------------------------

  const educationHost = $("educationList");

  if (educationHost) {
    educationHost.innerHTML = (EDUCATION || [])
      .map(item => `
        <article class="timeline-item">
          <div class="timeline-date">${escapeHTML(item.years)}</div>
          <div class="timeline-marker"></div>
          <div class="timeline-body">
            <div class="timeline-topline">
              <h3>${formatFormula(item.degree)}</h3>
              ${item.current
                ? '<span class="status-badge current">Ongoing</span>'
                : ""}
            </div>
            <h4>${escapeHTML(item.institution)}</h4>
            <p class="item-location">${escapeHTML(item.location)}</p>
            <p class="item-description">${formatFormula(item.description)}</p>
            <div class="detail-tags">
              ${(item.details || [])
                .map(detail => `<span>${escapeHTML(detail)}</span>`)
                .join("")}
            </div>
          </div>
        </article>
      `)
      .join("");
  }

  // ----------------------------------------------------------
  // RESEARCH EXPERIENCE
  // ----------------------------------------------------------

  const experienceHost = $("experienceList");

  if (experienceHost) {
    experienceHost.innerHTML = (EXPERIENCE || [])
      .map((item, index) => `
        <article class="experience-card">
          <div class="experience-number">${String(index + 1).padStart(2, "0")}</div>
          <div class="experience-content">
            <div class="experience-meta">
              <span>${escapeHTML(item.type)}</span>
              <span>${escapeHTML(item.period)}</span>
            </div>
            <h3>${formatFormula(item.title)}</h3>
            <h4>${escapeHTML(item.role)}</h4>
            <p>${formatFormula(item.description)}</p>
          </div>
        </article>
      `)
      .join("");
  }

  // ----------------------------------------------------------
  // RESEARCH INTERESTS
  // ----------------------------------------------------------

  const researchHost = $("researchGrid");

  if (researchHost) {
    researchHost.innerHTML = (INTERESTS || [])
      .map(item => `
        <article class="research-card">
          <span class="research-number">${escapeHTML(item.icon)}</span>
          <h3>${formatFormula(item.title)}</h3>
          <p>${formatFormula(item.description)}</p>
          <span class="research-arrow">↗</span>
        </article>
      `)
      .join("");
  }

  // ----------------------------------------------------------
  // PUBLICATIONS: SEARCH, FILTER AND SHOW MORE
  // ----------------------------------------------------------

  const publicationHost = $("publicationList");
  const searchInput = $("publicationSearch");
  const filterHost = $("publicationFilters");
  const countHost = $("publicationCount");
  const showMoreButton = $("showMoreButton");

  let currentFilter = "all";
  let searchTerm = "";
  let showAllPublications = false;

  const initialPublicationLimit = 4;

  const makeCitation = paper => {
    const doiURL = paper.doi
      ? ` https://doi.org/${paper.doi}`
      : "";

    return `${paper.authors} (${paper.year}). ${paper.title}. ${paper.journal}.${doiURL}`;
  };

  function renderPublications() {
    if (!publicationHost) return;

    const filtered = (PUBLICATIONS || []).filter(paper => {
      const statusMatch =
        currentFilter === "all" ||
        paper.status === currentFilter;

      const searchable = [
        paper.title,
        paper.authors,
        paper.journal,
        paper.year,
        paper.doi
      ].join(" ").toLowerCase();

      return statusMatch && searchable.includes(searchTerm);
    });

    const shouldShowAll =
      showAllPublications ||
      searchTerm.length > 0 ||
      currentFilter !== "all";

    const visible = shouldShowAll
      ? filtered
      : filtered.slice(0, initialPublicationLimit);

    if (countHost) {
      countHost.textContent =
        `${filtered.length} ${filtered.length === 1 ? "publication" : "publications"} found`;
    }

    publicationHost.innerHTML = visible.length
      ? visible.map(paper => {
          const index = PUBLICATIONS.indexOf(paper);
          const doi = paper.doi ? safeURL(`https://doi.org/${paper.doi}`) : "";

          const statusLabel = paper.status === "under-review"
            ? '<span class="publication-status pending">Under review</span>'
            : '<span class="publication-status published">Published</span>';

          return `
            <article class="publication-item">
              <div class="publication-year">${escapeHTML(paper.year)}</div>

              <div class="publication-content">
                <div class="publication-title-row">
                  <h3>${formatFormula(paper.title)}</h3>
                  ${statusLabel}
                </div>

                <p class="publication-authors">${escapeHTML(paper.authors)}</p>
                <p class="publication-journal">${escapeHTML(paper.journal)}</p>

                <div class="publication-actions">
                  ${doi
                    ? `<a href="${escapeHTML(doi)}"
                         target="_blank"
                         rel="noopener noreferrer">View DOI ↗</a>`
                    : ""}
                  <button type="button"
                          class="copy-citation"
                          data-copy-index="${index}">
                    Copy citation
                  </button>
                </div>
              </div>
            </article>`;
        }).join("")
      : '<p class="empty-state">No publications match your search.</p>';

    if (showMoreButton) {
      const hasMore = filtered.length > initialPublicationLimit;

      showMoreButton.hidden = !hasMore || shouldShowAll;
      showMoreButton.textContent = "Show all publications";
    }
  }

  if (searchInput) {
    searchInput.addEventListener("input", event => {
      searchTerm = event.target.value.trim().toLowerCase();
      showAllPublications = false;
      renderPublications();
    });
  }

  if (filterHost) {
    filterHost.addEventListener("click", event => {
      const button = event.target.closest("[data-filter]");
      if (!button) return;

      currentFilter = button.dataset.filter;
      showAllPublications = false;

      filterHost.querySelectorAll("[data-filter]").forEach(item => {
        item.classList.toggle("active", item === button);
      });

      renderPublications();
    });
  }

  if (showMoreButton) {
    showMoreButton.addEventListener("click", () => {
      showAllPublications = true;
      renderPublications();
    });
  }

  renderPublications();

  // ----------------------------------------------------------
  // CONFERENCE PRESENTATIONS
  // ----------------------------------------------------------

  const conferenceHost = $("conferenceList");

  if (conferenceHost) {
    conferenceHost.innerHTML = (TALKS || [])
      .map(item => `
        <article class="timeline-item">
          <div class="timeline-date">${escapeHTML(item.date)}</div>
          <div class="timeline-marker"></div>
          <div class="timeline-body">
            <span class="conference-type">${escapeHTML(item.type)}</span>
            <h3>${formatFormula(item.title)}</h3>
            <h4>${escapeHTML(item.event)}</h4>
          </div>
        </article>
      `)
      .join("");
  }

  // ----------------------------------------------------------
  // TECHNICAL SKILLS
  // ----------------------------------------------------------

  const skillsHost = $("skillsGrid");

  if (skillsHost) {
    skillsHost.innerHTML = Object.entries(SKILLS || {})
      .map(([category, skills], index) => `
        <article class="skill-card">
          <span class="skill-index">${String(index + 1).padStart(2, "0")}</span>
          <h3>${escapeHTML(category)}</h3>
          <div class="skill-tags">
            ${(skills || [])
              .map(skill => `<span>${escapeHTML(skill)}</span>`)
              .join("")}
          </div>
        </article>
      `)
      .join("");
  }

  // ----------------------------------------------------------
  // CONTACT AND FOOTER
  // ----------------------------------------------------------

  setText("contactText", CONTACT_TEXT || "");

  const contactEmail = $("contactEmail");

  if (contactEmail) {
    contactEmail.textContent = PROFILE.email || "";
    contactEmail.href = PROFILE.email
      ? `mailto:${PROFILE.email}`
      : "#";
  }

  const contactActions = $("contactActions");

  if (contactActions) {
    const email = PROFILE.email
      ? `<a href="mailto:${escapeHTML(PROFILE.email)}">Send an email ↗</a>`
      : "";

    const websiteLinks = (LINKS || [])
      .filter(item => item[0] !== "Email" && safeURL(item[1]))
      .map(item => `
        <a href="${escapeHTML(safeURL(item[1]))}"
           target="_blank"
           rel="noopener noreferrer">
          ${escapeHTML(item[0])} ↗
        </a>`)
      .join("");

    contactActions.innerHTML = email + websiteLinks;
  }

  // ----------------------------------------------------------
  // COPY CITATION
  // ----------------------------------------------------------

  const toast = $("toast");
  let toastTimer;

  function showToast(message) {
    if (!toast) return;

    toast.textContent = message;
    toast.classList.add("visible");

    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => {
      toast.classList.remove("visible");
    }, 2400);
  }

  async function copyText(text) {
    try {
      if (navigator.clipboard && window.isSecureContext) {
        await navigator.clipboard.writeText(text);
      } else {
        const field = document.createElement("textarea");
        field.value = text;
        field.style.position = "fixed";
        field.style.opacity = "0";
        document.body.appendChild(field);
        field.select();

        const copied = document.execCommand("copy");
        field.remove();

        if (!copied) throw new Error("Copy failed");
      }

      showToast("Citation copied to clipboard.");
    } catch (error) {
      showToast("Unable to copy. Please copy the citation manually.");
    }
  }

  document.addEventListener("click", event => {
    const button = event.target.closest("[data-copy-index]");
    if (!button) return;

    const index = Number(button.dataset.copyIndex);
    const paper = PUBLICATIONS[index];

    if (!paper) return;

    copyText(makeCitation(paper));
  });

  // ----------------------------------------------------------
  // DARK / LIGHT MODE
  // ----------------------------------------------------------

  const themeToggle = $("themeToggle");
  const themeIcon = $("themeIcon");
  const root = document.documentElement;

  let savedTheme = null;

  try {
    savedTheme = localStorage.getItem("emon-portfolio-theme");
  } catch (error) {
    savedTheme = null;
  }

  const prefersDark = window.matchMedia &&
    window.matchMedia("(prefers-color-scheme: dark)").matches;

  function setTheme(theme) {
    root.dataset.theme = theme;

    if (themeIcon) {
      themeIcon.textContent = theme === "dark" ? "☀" : "☾";
    }

    if (themeToggle) {
      themeToggle.setAttribute(
        "aria-label",
        theme === "dark" ? "Switch to light theme" : "Switch to dark theme"
      );
    }

    try {
      localStorage.setItem("emon-portfolio-theme", theme);
    } catch (error) {
      // The theme still works if browser storage is unavailable.
    }
  }

  setTheme(savedTheme || (prefersDark ? "dark" : "light"));

  if (themeToggle) {
    themeToggle.addEventListener("click", () => {
      setTheme(root.dataset.theme === "dark" ? "light" : "dark");
    });
  }

  // ----------------------------------------------------------
  // MOBILE NAVIGATION
  // ----------------------------------------------------------

  const menuToggle = $("menuToggle");
  const mainMenu = $("mainMenu");

  function closeMenu() {
    if (!menuToggle || !mainMenu) return;

    menuToggle.classList.remove("open");
    mainMenu.classList.remove("open");
    menuToggle.setAttribute("aria-expanded", "false");
    menuToggle.setAttribute("aria-label", "Open navigation");
  }

  if (menuToggle && mainMenu) {
    menuToggle.addEventListener("click", () => {
      const opening = !mainMenu.classList.contains("open");

      menuToggle.classList.toggle("open", opening);
      mainMenu.classList.toggle("open", opening);
      menuToggle.setAttribute("aria-expanded", String(opening));
      menuToggle.setAttribute(
        "aria-label",
        opening ? "Close navigation" : "Open navigation"
      );
    });

    mainMenu.querySelectorAll("a").forEach(link => {
      link.addEventListener("click", closeMenu);
    });

    document.addEventListener("keydown", event => {
      if (event.key === "Escape") closeMenu();
    });
  }

  // ----------------------------------------------------------
  // SCROLL PROGRESS AND BACK TO TOP
  // ----------------------------------------------------------

  const progressBar = $("readingProgress");
  const backToTop = $("backToTop");

  function updateScrollUI() {
    const doc = document.documentElement;
    const maxScroll = doc.scrollHeight - doc.clientHeight;
    const progress = maxScroll > 0
      ? (doc.scrollTop / maxScroll) * 100
      : 0;

    if (progressBar) {
      progressBar.style.width = `${progress}%`;
    }

    if (backToTop) {
      backToTop.classList.toggle("visible", doc.scrollTop > 500);
    }
  }

  window.addEventListener("scroll", updateScrollUI, { passive: true });
  updateScrollUI();

  if (backToTop) {
    backToTop.addEventListener("click", () => {
      window.scrollTo({ top: 0, behavior: "smooth" });
    });
  }

  // ----------------------------------------------------------
  // ACTIVE NAVIGATION AND REVEAL ANIMATIONS
  // ----------------------------------------------------------

  const reduceMotion = window.matchMedia &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  const sections = document.querySelectorAll("main section[id]");
  const menuLinks = document.querySelectorAll("#mainMenu a");

  if ("IntersectionObserver" in window && !reduceMotion) {
    const revealObserver = new IntersectionObserver(entries => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add("revealed");
          revealObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.10 });

    document.querySelectorAll(".reveal").forEach(element => {
      revealObserver.observe(element);
    });
  } else {
    document.querySelectorAll(".reveal").forEach(element => {
      element.classList.add("revealed");
    });
  }

  if ("IntersectionObserver" in window) {
    const navObserver = new IntersectionObserver(entries => {
      entries.forEach(entry => {
        if (!entry.isIntersecting) return;

        menuLinks.forEach(link => {
          const active = link.getAttribute("href") === `#${entry.target.id}`;
          link.classList.toggle("active", active);
        });
      });
    }, {
      rootMargin: "-30% 0px -60% 0px"
    });

    sections.forEach(section => navObserver.observe(section));
  }

  // ----------------------------------------------------------
  // EXTERNAL LINK SAFETY
  // ----------------------------------------------------------

  document.querySelectorAll('a[target="_blank"]').forEach(link => {
    link.setAttribute("rel", "noopener noreferrer");
  });

})();
